const cd=document.getElementById('cd');if(cd){setInterval(()=>{const d=new Date(cd.dataset.date)-new Date();cd.textContent=d<=0?'Hari Tari Nasional dimulai!':Math.floor(d/86400000)+' hari '+Math.floor((d%86400000)/3600000)+' jam';},1000)}document.querySelectorAll('.prov').forEach(p=>p.onclick=()=>document.getElementById('map-info').textContent='Provinsi '+p.dataset.name+': klik Jelajahi Tari untuk detail.');const s=document.getElementById('search');if(s){s.addEventListener('input',async()=>{const r=await fetch('?r=tari_ajax&q='+encodeURIComponent(s.value));const d=await r.json();document.getElementById('tari-list').innerHTML=d.map(x=>`<div class='col-md-3'><div class='card sky mb-3'><img loading='lazy' src='${x.gambar}' class='card-img-top'><div class='card-body'><h6>${x.nama_tari}</h6><small>${x.provinsi} • ${x.kategori}</small></div></div></div>`).join('')})}
